    vnFlexGrow = input<string>("1");
}

@Directive({
    selector: "[vnFlexFull]",
    standalone: true
})
export class FlexFull {
    @HostBinding("style.width") flexFull = "100%"
}

@Directive({
    selector: "[vnFlexGap]",
    standalone: true
})
export class FlexGap {
    vnFlexGap = input("1em")
    @HostBinding("style.gap") flexFull = this.vnFlexGap();
}


@NgModule({
    imports: [Flex, FlexGrow, FlexFull],
